                {"name": "casse", "code": "docs = ['Docker Compose orchestre']\nassert rechercher(docs, 'docker') == ['Docker Compose orchestre']"},
                {"name": "ordre_stable", "code": "docs = ['x a', 'y a']\nassert rechercher(docs, 'a', k=2) == ['x a', 'y a']"},
